        # Make a copy to avoid mutating input dict
        self.available_rooms = dict(rooms)
        # Structure: {'single': {'guest 1': 2, ...}, ...}
        self.booked_rooms = {room_type: {} for room_type in self.available_rooms}

    def book_room(self, room_type, room_number, name):
        """
        Book rooms for a guest if available.
        """
