class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'
        """

        # Pattern for decimal: &#65;
        # Pattern for hex:     &#x41; or &#X41;
        def replace_entity(match):
            full = match.group(0)
            dec = match.group(1)
            hex_ = match.group(2)
            try:
                if dec is not None:
                    codepoint = int(dec)
                elif hex_ is not None:
                    codepoint = int(hex_, 16)
                else:
                    return full  # Should not happen
                # Only replace valid Unicode codepoints
                if 0 <= codepoint <= 0x10FFFF:
                    return chr(codepoint)
                else:
                    return full
            except Exception:
                return full

        # Regex: group(1) is decimal, group(2) is hex
        pattern = re.compile(r'&#(\d+);|&#[xX]([0-9a-fA-F]+);')
        return pattern.sub(replace_entity, string)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True
        """
        if not isinstance(char, str) or len(char) != 1:
            return False
        return char.lower() in '0123456789abcdef'

import PyPDF2

class PDFHandler:
    """
    The class allows merging multiple PDF files into one and extracting text from PDFs using PyPDF2 library.
    """

    def __init__(self, filepaths):
        """
        takes a list of file paths filepaths as a parameter.
        It creates a list named readers using PyPDF2, where each reader opens a file from the given paths.
        """
        self.filepaths = filepaths
        self._file_handles = []
        self.readers = []
        for fp in filepaths:
            try:
                f = open(fp, 'rb')
                reader = PyPDF2.PdfFileReader(f)
                if reader.isEncrypted:
                    try:
                        reader.decrypt('')
                    except Exception:
                        f.close()
                        raise ValueError(f"File {fp} is encrypted and cannot be read.")
                self._file_handles.append(f)
                self.readers.append(reader)
            except Exception as e:
                # Clean up any opened files
                for fh in self._file_handles:
                    fh.close()
                raise RuntimeError(f"Error opening {fp}: {e}")

    def merge_pdfs(self, output_filepath):
        """
        Read files in self.readers which stores handles to multiple PDF files.
        Merge them to one pdf and update the page number, then save in disk.
        :param output_filepath: str, ouput file path to save to
        :return: str, "Merged PDFs saved at {output_filepath}" if successfully merged
        """
        if not self.readers:
            raise ValueError("No PDF files to merge.")
        merger = PyPDF2.PdfFileMerger()
        for reader in self.readers:
            merger.append(reader)
        try:
            with open(output_filepath, 'wb') as fout:
                merger.write(fout)
            return f"Merged PDFs saved at {output_filepath}"
        except Exception as e:
            raise RuntimeError(f"Failed to write merged PDF: {e}")

    def extract_text_from_pdfs(self):
        """
        Extract text from pdf files in self.readers
        :return pdf_texts: list of str, each element is the text of one pdf file
        """
        pdf_texts = []
        for reader in self.readers:
            text = ""
            for page_num in range(reader.numPages):
                page = reader.getPage(page_num)
                # PyPDF2 uses extractText() in older versions, extract_text() in newer
                if hasattr(page, "extract_text"):
                    page_text = page.extract_text()
                else:
                    page_text = page.extractText()
                if page_text:
                    text += page_text
            pdf_texts.append(text)
        return pdf_texts

    def __del__(self):
        # Close all open file handles
        for fh in getattr(self, '_file_handles', []):
            try:
                fh.close()
            except Exception:
                pass

class PushBoxGame:
    """
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    """

    def __init__(self, map):
        """
        Initialize the push box game with the map and various attributes.
        """
        self.map = map
        self.rows = len(map)
        self.cols = len(map[0]) if self.rows > 0 else 0
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        """
        Initialize the game by setting the positions of the player, targets, and boxes based on the map.
        """
        self.targets = []
        self.boxes = []
        for r in range(self.rows):
            for c in range(self.cols):
                ch = self.map[r][c]
                if ch == 'O':
                    self.player_row = r
                    self.player_col = c
                elif ch == 'G':
                    self.targets.append((r, c))
                elif ch == 'X':
                    self.boxes.append((r, c))
        self.target_count = len(self.targets)
        self.is_game_over = False

    def check_win(self):
        """
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of self.is_game_over.
        :return self.is_game_over: True if all the boxes are placed on target positions, or False otherwise.
        """
        # All boxes must be on targets
        box_set = set(self.boxes)
        target_set = set(self.targets)
        if all(box in target_set for box in box_set) and len(self.boxes) == self.target_count:
            self.is_game_over = True
        else:
            self.is_game_over = False
        return self.is_game_over

    def move(self, direction):
        """
        Move the player based on the specified direction and check if the game is won.
        """
        if self.is_game_over:
            return True

        dir_map = {
            'w': (-1, 0),
            's': (1, 0),
            'a': (0, -1),
            'd': (0, 1)
        }
        if direction not in dir_map:
            return self.is_game_over

        dr, dc = dir_map[direction]
        nr, nc = self.player_row + dr, self.player_col + dc

        # Check bounds
        if not (0 <= nr < self.rows and 0 <= nc < self.cols):
            return self.check_win()

        dest_cell = self.map[nr][nc]
        box_positions = set(self.boxes)

        if dest_cell == '#':
            # Wall
            return self.check_win()
        elif (nr, nc) in box_positions:
            # Try to push the box
            br, bc = nr + dr, nc + dc
            if not (0 <= br < self.rows and 0 <= bc < self.cols):
                return self.check_win()
            box_dest_cell = self.map[br][bc]
            if box_dest_cell == '#' or (br, bc) in box_positions:
                # Can't push box
                return self.check_win()
            # Move box
            self.boxes = [
                (br, bc) if (r, c) == (nr, nc) else (r, c)
                for (r, c) in self.boxes
            ]
            # Move player
            self.player_row, self.player_col = nr, nc
        else:
            # Move player if not wall or box
            self.player_row, self.player_col = nr, nc

        return self.check_win()

    def print_map(self):
        """
        Print the current state of the map.
        """
        # Build a grid for display
        grid = [list(row) for row in self.map]
        # Place targets first (in case overwritten)
        for r, c in self.targets:
            if grid[r][c] == ' ':
                grid[r][c] = 'G'
        # Place boxes
        for r, c in self.boxes:
            if grid[r][c] == 'G':
                grid[r][c] = 'B'  # Box on target
            else:
                grid[r][c] = 'X'
        # Place player
        pr, pc = self.player_row, self.player_col
        if grid[pr][pc] == 'G':
            grid[pr][pc] = 'P'  # Player on target
        elif grid[pr][pc] == 'X':
            grid[pr][pc] = 'Q'  # Player on box (shouldn't happen in Sokoban)
        else:
            grid[pr][pc] = 'O'
        # Print
        for row in grid:
            print(' '.join(row))

class ShoppingCart:
    """
    The class manages items, their prices, quantities, and allows to add, remove, view items, and calculate the total price.
    """

    def __init__(self):
        """
        Initialize the items representing the shopping list as an empty dictionary
        """
        self.items = {}

    def add_item(self, item, price, quantity=1):
        """
        Add item information to the shopping list items, including price and quantity. The default quantity is 1
        :param item: string, Item to be added
        :param price: float, The price of the item
        :param quantity:int, The number of items, defaults to 1
        :return:None
        """
        if not isinstance(item, str) or not item:
            raise ValueError("Item name must be a non-empty string.")
        if not isinstance(price, (int, float)) or price <= 0:
            raise ValueError("Price must be a positive number.")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be a positive integer.")

        if item in self.items:
            # Update price and add quantity
            self.items[item]["price"] = price
            self.items[item]["quantity"] += quantity
        else:
            self.items[item] = {"price": price, "quantity": quantity}

    def remove_item(self, item, quantity=1):
        """
        Subtract the specified quantity of item from the shopping list items
        :param item:string, Item to be subtracted in quantity
        :param quantity:int, Quantity to be subtracted
        :return:None
        """
        if not isinstance(item, str) or not item:
            raise ValueError("Item name must be a non-empty string.")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be a positive integer.")

        if item not in self.items:
            # Item not in cart, do nothing
            return

        if quantity >= self.items[item]["quantity"]:
            # Remove item entirely
            del self.items[item]
        else:
            self.items[item]["quantity"] -= quantity

    def view_items(self) -> dict:
        """
        Return the current shopping list items
        :return:dict, the current shopping list items
        """
        # Return a copy to prevent external modification
        return dict(self.items)

    def total_price(self) -> float:
        """
        Calculate the total price of all items in the shopping list, which is the quantity of each item multiplied by the price
        :return:float, the total price of all items in the shopping list
        """
        total = 0.0
        for item_info in self.items.values():
            total += item_info["price"] * item_info["quantity"]
        return total

class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    """

    @staticmethod
    def _quote(value):
        # Always quote as string for simplicity
        return f"'{value}'"

    @staticmethod
    def _format_where(where):
        if not where:
            return ''
        parts = [f"{k}={SQLQueryBuilder._quote(v)}" for k, v in where.items()]
        return ' WHERE ' + ' AND '.join(parts)

    @staticmethod
    def _format_columns(columns):
        if columns == '*' or columns is None:
            return '*'
        return ', '.join(columns)

    @staticmethod
    def select(table, columns='*', where=None):
        """
        Generate the SELECT SQL statement from the given parameters.
        """
        cols = SQLQueryBuilder._format_columns(columns)
        query = f"SELECT {cols} FROM {table}"
        query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def insert(table, data):
        """
        Generate the INSERT SQL statement from the given parameters.
        """
        if not data or not isinstance(data, dict):
            raise ValueError("Data for insert must be a non-empty dict")
        columns = ', '.join(data.keys())
        values = ', '.join(SQLQueryBuilder._quote(v) for v in data.values())
        query = f"INSERT INTO {table} ({columns}) VALUES ({values})"
        return query

    @staticmethod
    def delete(table, where=None):
        """
        Generate the DELETE SQL statement from the given parameters.
        """
        query = f"DELETE FROM {table}"
        query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def update(table, data, where=None):
        """
        Generate the UPDATE SQL statement from the given parameters.
        """
        if not data or not isinstance(data, dict):
            raise ValueError("Data for update must be a non-empty dict")
        set_clause = ', '.join(f"{k}={SQLQueryBuilder._quote(v)}" for k, v in data.items())
        query = f"UPDATE {table} SET {set_clause}"
        query += SQLQueryBuilder._format_where(where)
        return query

