from collections import Counter

class Statistics3:
    """
    Implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def median(data):
        """
        calculates the median of the given list.
        :param data: the given list, list.
        :return: the median of the given list, float.
        """
        if not data:
            raise ValueError("median() arg is an empty sequence")
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0
        else:
            return float(sorted_data[mid])

    @staticmethod
    def mode(data):
        """
        calculates the mode of the given list.
        :param data: the given list, list.
        :return: the mode of the given list, list.
        """
        if not data:
            raise ValueError("mode() arg is an empty sequence")
        counts = Counter(data)
        max_count = max(counts.values())
        return sorted([k for k, v in counts.items() if v == max_count])

    @staticmethod
    def mean(data):
        """
        calculates the mean of the given list.
        :param data: the given list, list.
        :return: the mean of the given list, float.
        """
        if not data:
            raise ValueError("mean() arg is an empty sequence")
        return sum(data) / len(data)

    @staticmethod
    def standard_deviation(data):
        """
        calculates the standard deviation of the given list.
        :param data: the given list, list.
        :return: the standard deviation of the given list, float.
        """
        n = len(data)
        if n < 2:
            raise ValueError("standard_deviation requires at least two data points")
        mean = Statistics3.mean(data)
        variance = sum((x - mean) ** 2 for x in data) / (n - 1)
        return math.sqrt(variance)

    @staticmethod
    def correlation(x, y):
        """
        calculates the correlation of the given list.
        :param x: the given list, list.
        :param y: the given list, list.
        :return: the correlation of the given list, float.
        """
        if len(x) != len(y):
            raise ValueError("correlation() lists must have the same length")
        n = len(x)
        if n < 2:
            raise ValueError("correlation() requires at least two data points")
        mean_x = Statistics3.mean(x)
        mean_y = Statistics3.mean(y)
        std_x = Statistics3.standard_deviation(x)
        std_y = Statistics3.standard_deviation(y)
        if std_x == 0 or std_y == 0:
            return 0.0
        cov = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y)) / (n - 1)
        return cov / (std_x * std_y)

    @staticmethod
    def correlation_matrix(data):
        """
        calculates the correlation matrix of the given list.
        :param data: the given list, list.
        :return: the correlation matrix of the given list, list.
        """
        if not data:
            raise ValueError("correlation_matrix() arg is an empty sequence")
        n_vars = len(data)
        lengths = [len(col) for col in data]
        if len(set(lengths)) != 1:
            raise ValueError("All variables must have the same number of observations")
        matrix = []
        for i in range(n_vars):
            row = []
            for j in range(n_vars):
                corr = Statistics3.correlation(data[i], data[j])
                row.append(corr)
            matrix.append(row)
        return matrix

    @staticmethod
    def z_score(data):
        """
        calculates the z-score of the given list.
        :param data: the given list, list.
        :return: the z-score of the given list, list.
        """
        if not data:
            raise ValueError("z_score() arg is an empty sequence")
        mean = Statistics3.mean(data)
        std = Statistics3.standard_deviation(data)
        if std == 0:
            return [0.0 for _ in data]
        return [(x - mean) / std for x in data]
